const teams=[
 ["conception","🧩 Conception","Choix techniques et architecture",65],
 ["modelisation-3D","🧱 Modélisation 3D","Modèles, plans et versions",40],
 ["materiaux","🧪 Matériaux","Matériaux et justification",80],
 ["fabrication","🛠️ Fabrication","Impression et fabrication",30],
 ["assemblage","🔩 Assemblage","Montage et intégration",0],
 ["essais","🏁 Essais","Mesures et validation",0],
 ["presentation","🎤 Présentation","Oral et communication",0]
];
const types={journal:{label:"Journal",icon:"📅",list:"journalList"},problem:{label:"Problèmes",icon:"⚠️",list:"problemList"},idea:{label:"Idées",icon:"💡",list:"ideaList"},test:{label:"Tests",icon:"🧪",list:"testList"}};
let me=null,progressState={},currentPage="accueil",teamView=null,teamTab="annotations",sketchDirty=false,journalItems=[],materialItems=[];
const $=id=>document.getElementById(id);
async function api(path,opt={}){if(!window.CEC_AUTH_API)throw new Error("Serveur de connexion non configuré");const r=await fetch(window.CEC_AUTH_API+"/api"+path,{credentials:"include",headers:{"Content-Type":"application/json"},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.error||"Erreur serveur");return d}

function grokErrorMessage(code){
 const messages={
  grok_not_configured:"La clé GROQ_API_KEY manque dans les secrets du Worker Cloudflare.",
  grok_image_format_unsupported:"Une photo utilise un format non pris en charge par le modèle GroqCloud. Réessaie après avoir converti les photos en JPG ou PNG.",
  grok_api_auth_failed:"La clé API GroqCloud est invalide ou révoquée. Vérifie GROQ_API_KEY dans Cloudflare.",
  grok_api_forbidden:"GroqCloud refuse l’accès à cette API ou à ce modèle. Vérifie les droits et les limites du compte GroqCloud.",
  grok_model_not_found:"Le modèle GroqCloud configuré n’existe pas ou n’est pas accessible à cette clé.",
  grok_payload_too_large:"La demande est trop volumineuse. Réessaie avec moins de photos.",
  grok_rate_limited:"La limite de requêtes GroqCloud est atteinte. Attends un peu puis réessaie.",
  grok_bad_request:"GroqCloud a refusé le format de la requête. Vérifie le détail de l’erreur.",
  grok_network_error:"Le Worker n’arrive pas à joindre l’API GroqCloud.",
  grok_provider_unavailable:"L’API GroqCloud est temporairement indisponible.",
  grok_empty_response:"Le modèle IA n’a renvoyé aucun contenu exploitable.",
  grok_request_failed:"La requête GroqCloud a échoué pour une raison non identifiée.",
  journal_generation_failed:"La génération du journal a échoué. Vérifie la configuration GroqCloud."
 };
 return messages[code]||code||"Erreur inconnue";
}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function roleName(){return me.role==="admin"?"👑 Administrateur":me.role==="prof"?"👨‍🏫 Professeur":me.is_leader?"⭐ Chef d’équipe":"👨‍🎓 Élève"}
function canEdit(){return me.role!=="prof"}
function percent(team){return progressState[team]??(teams.find(t=>t[0]===team)?.[3]??0)}
function teamName(id){return teams.find(t=>t[0]===id)?.[1]||"Équipe non attribuée"}
function flash(el,message,ok=false){if(!el)return;el.textContent=message;el.className=ok?"success":"error";el.hidden=false}
function progressRows(editable=false){return teams.map(t=>{const p=percent(t[0]);return '<div class="progressrow"><div class="progresshead"><span>'+t[1]+'</span><strong id="pct-'+t[0]+'">'+p+' %</strong></div><div class="bar"><div class="fill" style="width:'+p+'%"></div></div>'+(editable?'<input class="progress-slider" aria-label="Progression '+esc(t[1])+'" type="range" min="0" max="100" value="'+p+'" data-team="'+t[0]+'" '+(!canEdit()?'disabled':'')+'><div class="slider-foot"><span>0 %</span><span>Déplace le point pour actualiser</span><span>100 %</span></div>':'')+'</div>'}).join("")}
function shell(page,title,body){currentPage=page;$("page").innerHTML='<div class="hero"><div><span class="eyebrow">ESPACE PROJET</span><h2>'+title+'</h2></div></div>'+body;document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("active",b.dataset.page===page))}
function topIdentity(){const own=teams.find(t=>t[0]===me.team);$("identity").textContent=roleName()+" · "+me.username+(own?" · "+own[1]:"")}
function start(){if(me.role!=="prof"&&!me.team){$("appView").hidden=true;showTeamPicker();return} $("loginView").hidden=true;$("teamPicker").hidden=true;$("appView").hidden=false;$("adminNav").hidden=me.role!=="admin";$("leaderNav").hidden=!me.is_leader;$("aiNav").hidden=me.role==="prof";$("profileBtn").hidden=false;document.querySelectorAll(".nav").forEach(b=>b.onclick=()=>render(b.dataset.page));topIdentity();render("accueil")}
function showLogin(){$("appView").hidden=true;$("teamPicker").hidden=true;$("loginView").hidden=false;window.scrollTo(0,0)}
function showTeamPicker(){$("loginView").hidden=true;$("appView").hidden=true;$("teamPicker").hidden=false;$("teamPicker").innerHTML='<div class="team-picker-card"><span class="eyebrow">PREMIÈRE CONNEXION</span><h1>Choisis ton équipe</h1><div class="warning-red">⚠️ ATTENTION — CE CHOIX EST DÉFINITIF. Tu ne pourras pas le modifier toi-même après validation. Seul l’administrateur pourra le changer.</div><p>Ce choix permet de classer automatiquement tes annotations, idées, problèmes et tests dans le bon espace d’équipe.</p><form id="teamChoiceForm" class="form-grid"><label>Mon équipe<select name="team" required><option value="">Choisir une équipe…</option>'+teams.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join("")+'</select></label><button class="button primary" type="submit">Confirmer définitivement mon équipe</button><p id="teamChoiceMsg" hidden></p></form></div>';window.scrollTo(0,0)}
async function boot(){try{const d=await api("/me");me=d.user;start()}catch{showLogin()}}
$("loginForm").onsubmit=async e=>{e.preventDefault();$("loginError").hidden=true;const btn=$("loginForm").querySelector("button");btn.disabled=true;btn.textContent="Connexion…";try{const d=await api("/login",{method:"POST",body:JSON.stringify({username:$("username").value.trim(),password:$("password").value})});me=d.user;start();window.scrollTo(0,0)}catch(err){$("loginError").textContent=err.message==="invalid_credentials"?"Identifiant ou mot de passe incorrect.":err.message;$("loginError").hidden=false}finally{btn.disabled=false;btn.textContent="Se connecter"}};
$("logoutBtn").onclick=async()=>{try{await api("/logout",{method:"POST"})}catch{}me=null;showLogin()};
$("profileBtn").onclick=()=>render("profil");
document.addEventListener("submit",async e=>{
 if(e.target.id==="teamChoiceForm"){e.preventDefault();const msg=$("teamChoiceMsg"),team=new FormData(e.target).get("team");try{await api("/team/select",{method:"POST",body:JSON.stringify({team})});me.team=team;start()}catch(err){flash(msg,err.message)}return}
 if(e.target.id==="profileForm"){e.preventDefault();if(!canEdit())return;const f=e.target,msg=$("profileMsg"),username=f.elements.username.value.trim(),password=f.elements.password.value;try{const d=await api("/profile",{method:"POST",body:JSON.stringify({username,password:password||undefined})});me={...me,...d.user};topIdentity();flash(msg,"Profil mis à jour.",true);f.elements.password.value=""}catch(err){flash(msg,err.message)}return}
   if(e.target.id==="journalEntryForm"){e.preventDefault();if(!canEdit())return;const f=e.target,msg=$("journalFormMsg"),value=n=>String(f.elements[n]?.value||"").trim();const sections=[["Membres présents",value("attendees")],["Objectifs de la séance",value("objectives")],["Travail réalisé",value("work_done")],["Difficultés rencontrées",value("difficulties")],["Solutions apportées",value("solutions")],["Décisions techniques",value("decisions")],["Résultats / preuves",value("results")],["Prochaine séance",value("next_steps")]].filter(([,v])=>v).map(([label,v])=>"## "+label+"\n"+v);const content=(value("duration")?"Durée : "+value("duration")+"\n\n":"")+sections.join("\n\n");if(content.length>5000){flash(msg,"Le compte rendu est trop long : limite de 5 000 caractères.",false);return}try{const photos=await readPhotos(f.elements.photos.files);await api("/items",{method:"POST",body:JSON.stringify({type:"journal",title:value("title"),session_date:value("session_date"),content,photos})});f.reset();f.elements.session_date.value=new Date().toLocaleDateString("sv-SE",{timeZone:"Europe/Paris"});flash(msg,"Séance enregistrée dans "+teamName(me.team)+".",true);await loadItems("journal","journalList")}catch(err){flash(msg,err.message)}return}
  if(e.target.id==="annotationForm"){e.preventDefault();if(!canEdit())return;const f=e.target,msg=$("annotationMsg");try{const photos=await readPhotos(f.elements.photos.files);const title=f.elements.title.value.trim(),content=f.elements.content.value.trim();await api("/annotations",{method:"POST",body:JSON.stringify({content:title+"\n"+content,photos})});f.reset();flash(msg,"Annotation publiée dans "+teamName(me.team)+".",true);loadAnnotations()}catch(err){flash(msg,err.message)}return}
 if(e.target.matches(".item-form")){e.preventDefault();if(!canEdit())return;const f=e.target,msg=f.querySelector(".form-message"),data=Object.fromEntries(new FormData(f));try{data.photos=await readPhotos(f.elements.photos?.files);data.type=f.dataset.type;await api("/items",{method:"POST",body:JSON.stringify(data)});f.reset();flash(msg,"Enregistré dans "+teamName(me.team)+".",true);loadItems(data.type,types[data.type].list)}catch(err){flash(msg,err.message)}return}
 if(e.target.id==="privateNoteForm"){e.preventDefault();const f=e.target,msg=$("privateNoteMsg");try{const photos=await readPhotos(f.elements.photos.files);if(sketchDirty){photos.push({filename:"schema-dessine.png",mime_type:"image/png",data_url:$("sketchCanvas").toDataURL("image/png")})}await api("/private-notes",{method:"POST",body:JSON.stringify({title:f.elements.title.value,content:f.elements.content.value,photos})});f.reset();clearSketch();flash(msg,"Note enregistrée dans ton espace privé.",true);loadPrivateNotes()}catch(err){flash(msg,err.message)}return}
 if(e.target.id==="taskCreateForm"){e.preventDefault();if(!canEdit())return;const f=e.target,msg=f.querySelector(".form-message"),data=Object.fromEntries(new FormData(f));data.team=data.team||me.team;data.file_links=String(data.file_links||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{await api("/tasks",{method:"POST",body:JSON.stringify(data)});await loadTasks();const form=document.querySelector("#taskCreateForm");if(form)form.reset();flash($("taskBoardMsg"),"Tâche créée et partagée avec les utilisateurs autorisés.",true)}catch(err){flash(msg,err.message)}return}
 if(e.target.matches(".task-edit-form")){e.preventDefault();if(me.role==="prof")return;const f=e.target,id=f.dataset.taskEdit,msg=f.querySelector(".task-message"),data=Object.fromEntries(new FormData(f));data.file_links=String(data.file_links||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{await api("/tasks/"+id,{method:"PATCH",body:JSON.stringify(data)});await loadTasks();flash($("taskBoardMsg"),"Tâche mise à jour et historique enregistré.",true)}catch(err){flash(msg,err.message)}return}
 if(e.target.id==="aiJournalForm"){e.preventDefault();if(me.role!=="admin")return;const f=e.target,msg=$("aiJournalMsg");try{const d=await api("/ai/generate-journal",{method:"POST",body:JSON.stringify({date:f.elements.date.value})});flash(msg,"Journal du "+d.date+" généré. "+d.suggestions_added+" idée(s) ajoutée(s).",true);loadAiJournal();loadAiSuggestions()}catch(err){flash(msg,grokErrorMessage(err.message))}return}
  if(e.target.id==="aiChatForm"){e.preventDefault();if(me.role==="prof")return;const f=e.target,input=f.elements.question,msg=$("aiChatMsg"),log=$("aiChatLog"),question=input.value.trim();if(!question)return;log.insertAdjacentHTML("beforeend",'<div class="chat-bubble user-bubble"><b>Toi</b><p>'+esc(question)+'</p></div>');input.value="";flash(msg,"L’IA analyse les données du projet…",true);try{const d=await api("/ai/chat",{method:"POST",body:JSON.stringify({question})});log.insertAdjacentHTML("beforeend",'<div class="chat-bubble ai-bubble"><b>Assistant IA · lecture seule</b><p>'+esc(d.answer).replace(/\n/g,"<br>")+'</p><small>'+d.images_considered+' photo(s) transmises pour analyse</small></div>');msg.hidden=true;log.scrollTop=log.scrollHeight}catch(err){flash(msg,grokErrorMessage(err.message))}return}
  if(e.target.id==="createUser"){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),msg=$("adminMsg");try{await api("/users",{method:"POST",body:JSON.stringify(d)});f.reset();f.elements.team.disabled=false;flash(msg,"Compte créé.",true);loadUsers()}catch(err){flash(msg,friendlyAccountError(err.message))}}
});
document.addEventListener("input",e=>{if(!e.target.matches(".progress-slider"))return;const t=e.target.dataset.team,p=Number(e.target.value),row=e.target.closest(".progressrow");row.querySelector(".fill").style.width=p+"%";$("pct-"+t).textContent=p+" %"});
document.addEventListener("change",async e=>{if(e.target.matches("#createUser [name=role]")){const role=e.target.value,team=$("createUser").elements.team;if(role==="prof")team.value="";team.disabled=role==="prof";return}if(e.target.matches(".user-admin-card [name=role]")){const card=e.target.closest(".user-admin-card"),team=card.querySelector("[name=team]"),leader=card.querySelector("[name=is_leader]");if(e.target.value==="prof"){team.value="";leader.checked=false}leader.disabled=e.target.value!=="eleve"||!team.value||!card.querySelector("[name=active]").checked;return}if(e.target.matches(".user-admin-card [name=team],.user-admin-card [name=active]")){const card=e.target.closest(".user-admin-card"),leader=card.querySelector("[name=is_leader]");leader.disabled=card.querySelector("[name=role]").value!=="eleve"||!card.querySelector("[name=team]").value||!card.querySelector("[name=active]").checked;if(leader.disabled)leader.checked=false;return}if(!e.target.matches(".progress-slider"))return;const input=e.target;try{await api("/progress",{method:"POST",body:JSON.stringify({team:input.dataset.team,percent:Number(input.value)})});progressState[input.dataset.team]=Number(input.value)}catch(err){alert("Impossible d’enregistrer : "+err.message);loadProgress()}});
document.addEventListener("input",e=>{if(e.target.matches("#journalSearch"))renderJournalItems()});
document.addEventListener("change",e=>{if(e.target.matches("#journalTeamFilter,#journalYearFilter"))renderJournalItems()});
document.addEventListener("click",e=>{if(e.target.closest("#journalResetFilters")){["journalSearch","journalTeamFilter","journalYearFilter"].forEach(id=>{const el=$(id);if(el)el.value=""});renderJournalItems();return}if(e.target.closest("#exportPdf")){window.print();return}});
function itemForm(type,heading,date=false,teamField=false){if(!canEdit())return '<div class="readonly-note">👁️ Mode consultation : le compte professeur ne peut pas modifier le projet.</div>';return '<div class="panel"><h3>'+heading+'</h3><form class="form-grid item-form" data-type="'+type+'"><label>Titre<input name="title" maxlength="140" required placeholder="Donne un titre clair"></label>'+(date?'<label>Date prévue (facultatif)<input name="session_date" type="date"></label>':'')+(teamField&&me.role==="admin"?'<label>Équipe<select name="team">'+teams.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join("")+'</select></label>':'')+'<label>Description<textarea name="content" maxlength="5000" required placeholder="Décris les informations utiles…"></textarea></label><label>Photos (4 maximum)<input name="photos" type="file" accept="image/*" multiple></label><button class="button" type="submit">Enregistrer</button><p class="form-message" hidden></p></form></div>'}
function render(page="accueil"){if(page!=="equipes")teamView=null;topIdentity();const own=teams.find(t=>t[0]===me.team);
 if(page==="accueil"){shell(page,"Bonjour "+esc(me.username)+" 👋",'<div class="hero welcome"><div><span class="eyebrow">'+roleName().toUpperCase()+'</span><h2>'+(own?own[1]:"Vue globale")+'</h2><p>Ton espace de travail Course en Cours.</p></div></div><div class="grid"><div class="metric"><b>🏎️ Course en Cours</b><small>Projet collectif</small></div><div class="metric"><b>📅 Journal</b><small>Séances du projet</small></div><div class="metric"><b>💬 Annotations</b><small>Suivi du groupe</small></div><div class="metric"><b>🧪 Tests</b><small>Essais et résultats</small></div></div><div class="panel"><h3>📈 Progression globale</h3>'+progressRows(false)+'</div>')}
 else if(page==="progression"){shell(page,"📊 Progression du projet",'<div class="panel"><p class="muted">Déplace le curseur pour indiquer l’avancement estimé. Les valeurs sont partagées avec les autres utilisateurs.</p><div id="progressMessage" hidden></div>'+progressRows(true)+'</div>');loadProgress()}
 else if(page==="equipes"){shell(page,"👥 Les équipes",'<p class="muted">Ouvre une équipe pour consulter ses membres et ses travaux. Les équipes peuvent consulter les autres espaces, mais leurs publications restent classées dans leur équipe.</p><div class="team-list" id="teamList">Chargement…</div>');loadTeams()}
  else if(page==="taches"){shell(page,"🗂️ Tableau des tâches",'<div class="panel"><p class="muted">Un tableau partagé pour répartir le travail, suivre les échéances et garder un historique des changements. Les professeurs peuvent consulter les tâches, mais pas les modifier.</p></div>'+(canEdit()?'<div class="panel"><h3>➕ Nouvelle tâche</h3><form id="taskCreateForm" class="form-grid"><label>Titre<input name="title" maxlength="140" required placeholder="Ex. Finaliser le châssis"></label><label>Description<textarea name="description" maxlength="3000" required placeholder="Décris le résultat attendu et les étapes utiles."></textarea></label>'+(me.role==="admin"?'<label>Équipe responsable<select name="team" required>'+teams.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join("")+'</select></label>':'<input type="hidden" name="team" value="'+esc(me.team)+'"><p class="muted">Équipe responsable : '+esc(teamName(me.team))+'</p>')+'<label>Responsable (identifiant du compte, facultatif)<input name="assignee_username" maxlength="40" placeholder="Ex. eleve01"></label><div class="task-form-row"><label>Statut<select name="status"><option value="todo">À faire</option><option value="doing">En cours</option><option value="blocked">Bloqué</option><option value="done">Terminé</option></select></label><label>Priorité<select name="priority"><option value="low">Basse</option><option value="normal" selected>Normale</option><option value="high">Haute</option><option value="urgent">Urgente</option></select></label><label>Échéance<input name="due_date" type="date"></label></div><label>Liens vers les fichiers (une URL http(s) par ligne, 10 maximum)<textarea name="file_links" rows="3" placeholder="https://..."></textarea></label><button class="button" type="submit">Créer la tâche</button><p class="form-message" hidden></p></form></div>':'<div class="readonly-note">👁️ Mode consultation : le compte professeur peut consulter les tâches et leur historique.</div>')+'<div class="panel"><div class="task-board-heading"><h3>📋 Tâches du projet</h3><button class="button secondary" type="button" id="refreshTasks">Actualiser</button></div><p id="taskBoardMsg" hidden></p><div id="taskList" class="task-list">Chargement…</div></div>');loadTasks()}
  else if(page==="journal"){shell(page,"📅 Carnet de bord des séances",'<div class="panel journal-tools"><div><h3>Historique des séances</h3><p class="muted">Recherche et exporte les comptes rendus du projet.</p></div><button class="button secondary" id="exportPdf" type="button">🖨️ Exporter / PDF</button></div>'+(canEdit()?'<div class="panel journal-compose"><h3>📘 Documenter une séance</h3><form id="journalEntryForm" class="form-grid"><div class="journal-form-row"><label>Titre de la séance<input name="title" maxlength="140" required placeholder="Ex. Première version du châssis"></label><label>Date<input name="session_date" type="date" value="'+new Date().toLocaleDateString("sv-SE",{timeZone:"Europe/Paris"})+'" required></label><label>Durée<input name="duration" maxlength="40" placeholder="Ex. 1 h 30"></label></div><label>Membres présents<input name="attendees" maxlength="500" placeholder="Prénoms ou identifiants"></label><div class="journal-form-row"><label>Objectifs<textarea name="objectives" maxlength="1000" rows="3" required></textarea></label><label>Travail réalisé<textarea name="work_done" maxlength="2000" rows="3" required></textarea></label></div><div class="journal-form-row"><label>Difficultés<textarea name="difficulties" maxlength="800" rows="2"></textarea></label><label>Solutions<textarea name="solutions" maxlength="800" rows="2"></textarea></label></div><div class="journal-form-row"><label>Décisions techniques<textarea name="decisions" maxlength="800" rows="2"></textarea></label><label>Résultats / preuves<textarea name="results" maxlength="800" rows="2"></textarea></label></div><label>Prochaine séance<textarea name="next_steps" maxlength="800" rows="2"></textarea></label><label>Photos / preuves (4 maximum)<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><button class="button" type="submit">Enregistrer la séance</button><p id="journalFormMsg" class="form-message" hidden></p></form></div>':'<div class="readonly-note">👁️ Consultation seule : le professeur peut consulter les séances.</div>')+'<div class="panel"><div class="journal-filters"><label>Recherche<input id="journalSearch" type="search" placeholder="Titre, auteur, contenu…"></label><label>Équipe<select id="journalTeamFilter"><option value="">Toutes les équipes</option>'+teams.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join("")+'</select></label><label>Année<input id="journalYearFilter" type="number" min="2020" max="2100" placeholder="Toutes"></label><button class="button secondary" id="journalResetFilters" type="button">Réinitialiser</button></div><p id="journalCount" class="muted"></p><div id="journalList" class="item-list">Chargement…</div></div>');loadItems("journal","journalList")}
  else if(page==="journal-ia"){shell(page,"📘 Journal de bord (IA)",'<div class="panel"><p class="muted">Journal chronologique rédigé par l’IA à partir des données du projet. Consultable par les élèves, les professeurs et l’administrateur.</p>'+(me.role==="admin"?'<form id="aiJournalForm" class="form-grid"><label>Journée à documenter<input name="date" type="date" value="'+new Date().toLocaleDateString("sv-SE",{timeZone:"Europe/Paris"})+'" required></label><button class="button" type="submit">Générer / actualiser le journal avec l’IA</button><p id="aiJournalMsg" hidden></p></form>':'<div class="readonly-note">Le journal de bord est en lecture seule pour ce compte.</div>')+'</div><div class="panel"><h3>Journal jour par jour</h3><div id="aiJournalEntries" class="ai-entry-list">Chargement…</div></div>');loadAiJournal()}
  else if(page==="ia"){if(me.role==="prof"){render("journal-ia");return}shell(page,"🤖 Assistant IA",'<div class="private-banner">L’IA peut analyser les données et photos du projet et proposer des idées, mais ne peut modifier aucune fiche existante.</div><div class="panel"><h3>💬 Poser une question sur le projet</h3><div id="aiChatLog" class="ai-chat-log"><div class="chat-bubble ai-bubble"><b>Assistant IA · lecture seule</b><p>Je peux analyser la progression, les annotations, les problèmes, les essais et les photos du projet. Je ne modifie aucune donnée existante.</p></div></div><form id="aiChatForm" class="ai-chat-form"><label>Ta question<textarea name="question" maxlength="2000" required placeholder="Ex. Quels problèmes reviennent le plus souvent ?"></textarea></label><button class="button" type="submit">Demander à l’IA</button><p id="aiChatMsg" hidden></p></form></div><div class="panel"><h3>💡 Idées proposées par l’IA</h3><div id="aiSuggestions" class="ai-entry-list">Chargement…</div></div>');loadAiSuggestions()}
 else if(page==="annotations"){shell(page,"💬 Annotations",(canEdit()?'<div class="panel"><h3>Nouvelle annotation · '+esc(teamName(me.team))+'</h3><form id="annotationForm" class="form-grid"><label>Titre<input name="title" maxlength="140" required placeholder="Ex. Choix du matériau du châssis"></label><label>Annotation<textarea name="content" maxlength="2000" required placeholder="Décris ta remarque, une décision ou une question…"></textarea></label><label>Photos (4 maximum)<input name="photos" type="file" accept="image/*" multiple></label><button class="button" type="submit">Publier l’annotation</button><p id="annotationMsg" hidden></p></form></div>':'<div class="readonly-note">👁️ Mode consultation : le professeur peut lire les annotations, mais pas en ajouter.')+'<div class="panel"><h3>Toutes les annotations par équipe</h3><div id="annotationList" class="item-list">Chargement…</div></div>');loadAnnotations()}
 else if(page==="problemes"||page==="idees"||page==="tests"){const type=page==="problemes"?"problem":page==="idees"?"idea":"test",t=types[type];shell(page,t.icon+" "+t.label,itemForm(type,type==="problem"?"Signaler un problème":type==="idea"?"Proposer une idée":"Ajouter un test")+'<div class="panel"><h3>'+t.label+' — toutes les équipes</h3><div id="'+t.list+'" class="item-list">Chargement…</div></div>');loadItems(type,t.list)}
 else if(page==="profil"){shell(page,"👤 Mon profil",'<div class="panel"><h3>Informations du compte</h3>'+(canEdit()?'<form id="profileForm" class="form-grid"><label>Identifiant<input name="username" value="'+esc(me.username)+'" minlength="3" maxlength="40" required></label><label>Nouveau mot de passe <small>(laisser vide pour ne pas le changer)</small><input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="Au moins 8 caractères"></label><label>Rôle<input value="'+esc(roleName())+'" disabled></label><label>Équipe<input value="'+esc(teamName(me.team))+'" disabled></label><p class="muted">Le rôle et l’équipe ne peuvent pas être modifiés depuis ton profil.</p><button class="button" type="submit">Enregistrer les changements</button><p id="profileMsg" hidden></p></form>':'<div class="form-grid"><p>Identifiant : <b>'+esc(me.username)+'</b></p><p>Rôle : '+esc(roleName())+'</p><p>Équipe : '+esc(teamName(me.team))+'</p><p class="readonly-note">Le profil professeur est en lecture seule.</p></div>')+'</div>')}
 else if(page==="chef"){if(!me.is_leader){render("accueil");return}shell(page,"⭐ Espace privé du chef d’équipe",'<div class="private-banner">🔒 Espace strictement privé : tes notes, photos et schémas ne sont visibles que par toi, pas par les autres élèves ni le professeur.</div><div class="panel"><h3>Nouvelle note privée</h3><form id="privateNoteForm" class="form-grid"><label>Titre<input name="title" maxlength="140" required></label><label>Notes<textarea name="content" maxlength="5000" required placeholder="Plan d’action, idées à organiser, notes personnelles…"></textarea></label><label>Photos (4 maximum)<input name="photos" type="file" accept="image/*" multiple></label><div><b>Schéma personnel</b><p class="muted">Dessine directement dans la zone, puis enregistre la note.</p><canvas id="sketchCanvas" width="900" height="260"></canvas><button class="button secondary" type="button" id="clearSketch">Effacer le schéma</button></div><button class="button" type="submit">Enregistrer dans mon espace privé</button><p id="privateNoteMsg" hidden></p></form></div><div class="panel"><h3>Mes notes privées</h3><div id="privateNotes" class="item-list">Chargement…</div></div>');initSketch();loadPrivateNotes()}
 else if(page==="admin"){if(me.role!=="admin")return render("accueil");shell(page,"⚙️ Comptes et permissions",'<div class="permission-overview"><article><b>👩‍🎓 Élève</b><p>Travaille dans son équipe et participe au projet.</p></article><article><b>🧑‍🏫 Professeur</b><p>Consulte le projet sans modifier les données.</p></article><article><b>🔐 Administrateur</b><p>Gère les comptes, les rôles, les équipes et les accès.</p></article></div><div class="admin-grid"><div class="panel"><h3>Créer un compte</h3><form id="createUser" class="form-grid"><label>Identifiant<input name="username" minlength="3" maxlength="40" pattern="[A-Za-z0-9._-]{3,40}" required placeholder="ex. eleve01"></label><label>Mot de passe temporaire<input name="password" type="password" minlength="8" maxlength="256" required autocomplete="new-password"></label><label>Rôle<select name="role"><option value="eleve">Élève</option><option value="prof">Professeur (lecture seule)</option><option value="admin">Administrateur</option></select></label><label>Équipe<select name="team"><option value="">Aucune / à choisir plus tard</option>'+teams.map(t=>'<option value="'+t[0]+'">'+t[1]+'</option>').join("")+'</select></label><p class="muted">Un professeur ne peut pas être affecté à une équipe. Un identifiant doit contenir 3 à 40 caractères (lettres, chiffres, point, tiret ou souligné).</p><button class="button" type="submit">Créer le compte</button><p id="adminMsg" hidden></p></form></div><div class="panel"><h3>Comptes et accès</h3><p class="muted">Tu peux modifier le rôle, l’équipe, le statut du compte, le chef d’équipe ou réinitialiser le mot de passe. La désactivation révoque immédiatement les sessions.</p><div id="users" class="user-list">Chargement…</div></div></div>');loadUsers()}
}

const taskStatusLabels={todo:"À faire",doing:"En cours",blocked:"Bloqué",done:"Terminé"};
const taskPriorityLabels={low:"Basse",normal:"Normale",high:"Haute",urgent:"Urgente"};
const taskFieldLabels={title:"Titre",description:"Description",team:"Équipe",status:"Statut",priority:"Priorité",due_date:"Échéance",assignee_username:"Responsable",file_links:"Liens de fichiers"};
function taskValue(v){if(v===null||v===undefined||v==="")return "—";if(Array.isArray(v))return v.join(", ")||"—";if(taskStatusLabels[v])return taskStatusLabels[v];if(taskPriorityLabels[v])return taskPriorityLabels[v];if(typeof v==="object")return JSON.stringify(v);return String(v)}
async function loadTasks(){
 const el=$("taskList");if(!el)return;
 try{
  const d=await api("/tasks");
  if(!d.tasks.length){el.innerHTML='<p class="notice">Aucune tâche pour le moment. Créez la première tâche ci-dessus.</p>';return}
  el.innerHTML=d.tasks.map(t=>{
   const editable=me.role!=="prof"&&(me.role==="admin"||me.team===t.team);
   const links=Array.isArray(t.file_links)?t.file_links:[];
   const due=t.due_date?new Date(t.due_date+"T00:00:00").toLocaleDateString("fr-FR"):"Aucune échéance";
   const teamSelect=me.role==="admin"?'<label>Équipe<select name="team">'+teams.map(x=>'<option value="'+x[0]+'" '+(x[0]===t.team?"selected":"")+'>'+x[1]+'</option>').join("")+'</select></label>':'<input type="hidden" name="team" value="'+esc(t.team)+'">';
   const edit=editable?'<details class="task-edit"><summary>Modifier la tâche</summary><form class="form-grid task-edit-form" data-task-edit="'+t.id+'"><label>Titre<input name="title" maxlength="140" required value="'+esc(t.title)+'"></label><label>Description<textarea name="description" maxlength="3000" required>'+esc(t.description)+'</textarea></label>'+teamSelect+'<label>Responsable (identifiant)<input name="assignee_username" maxlength="40" value="'+esc(t.assignee_username||"")+'" placeholder="Laisser vide pour retirer le responsable"></label><div class="task-form-row"><label>Statut<select name="status">'+Object.entries(taskStatusLabels).map(([k,v])=>'<option value="'+k+'" '+(t.status===k?"selected":"")+'>'+v+'</option>').join("")+'</select></label><label>Priorité<select name="priority">'+Object.entries(taskPriorityLabels).map(([k,v])=>'<option value="'+k+'" '+(t.priority===k?"selected":"")+'>'+v+'</option>').join("")+'</select></label><label>Échéance<input name="due_date" type="date" value="'+esc(t.due_date||"")+'"></label></div><label>Liens de fichiers (une URL http(s) par ligne)<textarea name="file_links" rows="3">'+esc(links.join("\n"))+'</textarea></label><button class="button" type="submit">Enregistrer les modifications</button><p class="task-message" hidden></p></form></details>':'';
   return '<article class="task-card"><div class="task-card-top"><h4>'+esc(t.title)+'</h4><div class="task-badges"><span class="task-status status-'+esc(t.status)+'">'+esc(taskStatusLabels[t.status]||t.status)+'</span><span class="task-priority priority-'+esc(t.priority)+'">Priorité '+esc(taskPriorityLabels[t.priority]||t.priority)+'</span></div></div><p class="task-description">'+esc(t.description).replace(/\n/g,"<br>")+'</p><div class="task-meta"><span>👥 '+esc(teamName(t.team))+'</span><span>🙋 Responsable : '+esc(t.assignee_username||"Non attribué")+'</span><span>📅 '+esc(due)+'</span><span>Créée par '+esc(t.creator_username||"—")+'</span></div>'+(links.length?'<div class="task-links"><b>Fichiers associés :</b> '+links.map((u,i)=>'<a href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">Lien '+(i+1)+' ↗</a>').join(" · ")+'</div>':'')+edit+'<div class="task-footer"><button class="button secondary" type="button" data-task-history="'+t.id+'">🕘 Historique</button><span class="muted">Mise à jour : '+esc(new Date(String(t.updated_at).replace(" ","T")+"Z").toLocaleString("fr-FR"))+'</span></div><div class="task-history" id="taskHistory'+t.id+'" hidden></div></article>';
  }).join("");
 }catch(e){el.textContent="Impossible de charger les tâches : "+e.message}
}

async function readPhotos(files){const arr=[];for(const file of Array.from(files||[]).slice(0,4)){if(!file.type.startsWith("image/"))continue;const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,1200/im.width,1200/im.height),canvas=document.createElement("canvas");canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext("2d").drawImage(im,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",.68))};im.onerror=reject;im.src=fr.result};fr.onerror=reject;fr.readAsDataURL(file)});if(data.length<850000)arr.push({filename:file.name,mime_type:"image/jpeg",data_url:data})}return arr}
async function loadProgress(){try{const d=await api("/progress");d.progress.forEach(p=>{progressState[p.team]=p.percent;const input=document.querySelector('.progress-slider[data-team="'+p.team+'"]');if(input){input.value=p.percent;input.closest(".progressrow").querySelector(".fill").style.width=p.percent+"%";$("pct-"+p.team).textContent=p.percent+" %"}})}catch(e){}}
async function loadTeams(){try{const d=await api("/teams");d.progress.forEach(p=>progressState[p.team]=p.percent);$("teamList").innerHTML=teams.map(t=>{const members=d.users.filter(u=>u.team===t[0]);return '<details class="team-card"><summary><span>'+t[1]+'</span><span class="muted">'+members.length+' membre(s)</span><span class="badge">'+percent(t[0])+' %</span></summary><p>'+t[2]+'</p><div class="member-list">'+(members.length?members.map(m=>'<div class="member"><b>'+esc(m.username)+(m.is_leader?' ⭐':'')+'</b><span>'+(m.role==="prof"?"Professeur":m.role==="admin"?"Administrateur":m.is_leader?"Chef d’équipe":"Élève")+'</span><small>Mission : '+esc(t[2])+'</small></div>').join(""):'<p class="muted">Aucun membre affecté.</p>')+'</div><div class="team-subtabs">'+["annotations","problem","idea","test","journal"].map(tab=>'<button class="button secondary" data-team-open="'+t[0]+'" data-team-tab="'+tab+'">'+(tab==="annotations"?"💬 Annotations":types[tab]?.icon+" "+(types[tab]?.label||"Journal"))+'</button>').join("")+'</div></details>'}).join("")}catch(e){$("teamList").textContent="Impossible de charger : "+e.message}}
async function loadItems(type,target){try{const d=await api("/items?type="+encodeURIComponent(type)),el=$(target);if(type==="journal"){journalItems=d.items;renderJournalItems();return}if(!d.items.length){el.innerHTML='<p class="notice">Aucun élément pour le moment.</p>';return}el.innerHTML=d.items.map(i=>'<button class="item-card" data-item-id="'+i.id+'" data-item-type="'+type+'"><span class="item-title">'+esc(i.title)+'</span><span class="item-meta">'+esc(teamName(i.team))+' · '+esc(i.username)+' · '+new Date(i.created_at+"Z").toLocaleDateString("fr-FR")+'</span><span class="item-preview">'+esc(i.content.slice(0,130))+(i.content.length>130?"…":"")+'</span>'+(i.photos?.length?'<span class="photo-count">📷 '+i.photos.length+' photo(s)</span>':'')+'<span class="item-open">Ouvrir le détail →</span></button>').join("")}catch(e){$(target).textContent="Impossible de charger : "+e.message}}
function renderJournalItems(){const el=$("journalList");if(!el)return;const q=($("journalSearch")?.value||"").trim().toLocaleLowerCase("fr-FR"),team=$("journalTeamFilter")?.value||"",year=$("journalYearFilter")?.value||"";const items=journalItems.filter(i=>{const date=i.session_date||String(i.created_at||"").slice(0,10),hay=[i.title,i.content,i.username,teamName(i.team)].join(" ").toLocaleLowerCase("fr-FR");return(!q||hay.includes(q))&&(!team||i.team===team)&&(!year||date.startsWith(year))}).sort((a,b)=>String(b.session_date||b.created_at).localeCompare(String(a.session_date||a.created_at)));const count=$("journalCount");if(count)count.textContent=items.length+" séance(s) affichée(s) sur "+journalItems.length;if(!items.length){el.innerHTML='<div class="journal-empty"><b>Aucune séance trouvée</b><p>Modifie les filtres ou ajoute un compte rendu.</p></div>';return}el.innerHTML=items.map(i=>{const date=i.session_date||String(i.created_at||"").slice(0,10),parsed=date?new Date(date+"T12:00:00"):new Date(i.created_at+"Z"),excerpt=(i.content||"").replace(/##?\s/g,"").replace(/\s+/g," ").trim();return '<button class="item-card journal-card" data-item-id="'+i.id+'" data-item-type="journal"><span class="journal-date"><b>'+parsed.toLocaleDateString("fr-FR",{day:"2-digit"})+'</b><small>'+esc(parsed.toLocaleDateString("fr-FR",{month:"short",year:"numeric"}))+'</small></span><span class="journal-card-main"><span class="item-title">'+esc(i.title)+'</span><span class="item-meta">'+esc(teamName(i.team))+' · '+esc(i.username)+' · '+parsed.toLocaleDateString("fr-FR")+'</span><span class="item-preview">'+esc(excerpt.slice(0,180))+(excerpt.length>180?"…":"")+'</span>'+(i.photos?.length?'<span class="photo-count">📷 '+i.photos.length+' preuve(s)</span>':'')+'</span><span class="item-open">Lire →</span></button>'}).join("")}
async function loadAnnotations(){try{const d=await api("/annotations"),el=$("annotationList");if(!d.annotations.length){el.innerHTML='<p class="notice">Aucune annotation pour le moment.</p>';return}el.innerHTML=d.annotations.map(a=>{const parts=a.content.split("\n"),title=parts.shift()||"Annotation sans titre";return '<button class="item-card" data-annotation-id="'+a.id+'"><span class="item-title">'+esc(title)+'</span><span class="item-meta">'+esc(teamName(a.team))+' · '+esc(a.username)+' · '+new Date(a.created_at+"Z").toLocaleString("fr-FR")+'</span><span class="item-preview">'+esc(parts.join(" ").slice(0,140))+'</span>'+(a.photos?.length?'<span class="photo-count">📷 '+a.photos.length+' photo(s)</span>':'')+'<span class="item-open">Ouvrir l’annotation →</span></button>'}).join("")}catch(e){$("annotationList").textContent="Impossible de charger : "+e.message}}
async function openTeamTab(team,tab){teamView=team;teamTab=tab;const label=tab==="annotations"?"Annotations":types[tab]?.label||"Journal";shell("equipes",teamName(team)+' — '+label,'<div class="panel"><button class="button secondary" id="backTeams">← Retour aux équipes</button><h3>'+label+' de '+esc(teamName(team))+'</h3><div id="teamContent" class="item-list">Chargement…</div></div>');$("backTeams").onclick=()=>render("equipes");try{if(tab==="annotations"){const d=await api("/annotations"),items=d.annotations.filter(a=>a.team===team);renderTeamCards(items,"annotation")}else{const d=await api("/items?type="+encodeURIComponent(tab)),items=d.items.filter(i=>i.team===team);renderTeamCards(items,tab)}}catch(e){$("teamContent").textContent=e.message}}
function renderTeamCards(items,type){const el=$("teamContent");if(!items.length){el.innerHTML='<p class="notice">Cette équipe n’a pas encore publié de contenu dans cette rubrique.</p>';return}el.innerHTML=items.map(i=>'<button class="item-card" '+(type==="annotation"?'data-annotation-id="'+i.id+'"':'data-item-id="'+i.id+'" data-item-type="'+type+'"')+'><span class="item-title">'+esc(type==="annotation"?(i.content.split("\n")[0]||"Annotation"):i.title)+'</span><span class="item-meta">'+esc(i.username)+' · '+new Date(i.created_at+"Z").toLocaleDateString("fr-FR")+'</span><span class="item-preview">'+esc((type==="annotation"?i.content.split("\n").slice(1).join(" "):i.content).slice(0,140))+'</span>'+(i.photos?.length?'<span class="photo-count">📷 '+i.photos.length+' photo(s)</span>':'')+'<span class="item-open">Ouvrir →</span></button>').join("")}
function safePhotoDataUrl(value){const data=String(value??"");return data.length<=850000&&/^data:image\/(?:jpeg|png|webp);base64,(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(data)?data:""}
function photoGallery(photos){const safe=(photos||[]).map(p=>({data:safePhotoDataUrl(p.data_url),filename:p.filename})).filter(p=>p.data);return safe.length?'<div class="photo-gallery">'+safe.map(p=>'<a href="'+esc(p.data)+'" target="_blank" rel="noopener noreferrer"><img src="'+esc(p.data)+'" alt="'+esc(p.filename)+'" loading="lazy"></a>').join("")+'</div>':''}
document.addEventListener("click",async e=>{
 const refresh=e.target.closest("#refreshTasks");if(refresh){loadTasks();return}
 const historyBtn=e.target.closest("[data-task-history]");if(historyBtn){const id=historyBtn.dataset.taskHistory,box=$("taskHistory"+id);if(!box)return;if(!box.hidden){box.hidden=true;return}box.hidden=false;box.innerHTML='<p class="muted">Chargement de l’historique…</p>';try{const d=await api("/tasks/"+id+"/history");box.innerHTML=d.history.length?d.history.map(h=>{const changes=h.changes||{};const detail=h.action==="created"?'<p>Création de la tâche.</p>':'<ul>'+Object.entries(changes).map(([k,v])=>'<li><b>'+esc(taskFieldLabels[k]||k)+':</b> '+esc(taskValue(v.before))+' → '+esc(taskValue(v.after))+'</li>').join("")+'</ul>';return '<div class="task-history-row"><b>'+(h.action==="created"?"Tâche créée":"Modifications")+'</b><span>'+esc(h.actor_username)+' · '+esc(new Date(String(h.created_at).replace(" ","T")+"Z").toLocaleString("fr-FR"))+'</span>'+detail+'</div>'}).join(""):'<p class="muted">Aucun historique disponible.</p>'}catch(err){box.textContent="Impossible de charger l’historique : "+err.message}return}
 const teamBtn=e.target.closest("[data-team-open]");if(teamBtn){openTeamTab(teamBtn.dataset.teamOpen,teamBtn.dataset.teamTab);return}
 if(e.target.id==="clearSketch"){clearSketch();return}
 const ann=e.target.closest("[data-annotation-id]");if(ann){const d=await api("/annotations"),a=d.annotations.find(x=>String(x.id)===ann.dataset.annotationId);if(!a)return;const parts=a.content.split("\n"),title=parts.shift();shell("annotations","💬 "+esc(title),'<div class="panel detail-panel"><button class="button secondary" id="backToAnnotations">← Retour</button><p class="item-meta">'+esc(teamName(a.team))+' · '+esc(a.username)+' · '+new Date(a.created_at+"Z").toLocaleString("fr-FR")+'</p><div class="detail-content">'+esc(parts.join("\n")).replace(/\n/g,"<br>")+'</div>'+photoGallery(a.photos)+'</div>');$("backToAnnotations").onclick=()=>teamView?openTeamTab(teamView,teamTab):render("annotations");return}
 const item=e.target.closest("[data-item-id]");if(item){try{const d=await api("/items/"+item.dataset.itemId),i=d.item;const type=i.type,back=()=>teamView?openTeamTab(teamView,teamTab):render(type==="problem"?"problemes":type==="idea"?"idees":type==="test"?"tests":"journal");shell(type,types[type]?.icon+" "+esc(i.title),'<div class="panel detail-panel"><button class="button secondary" id="backToItems">← Retour</button><p class="item-meta">'+esc(teamName(i.team))+' · '+esc(i.username)+' · '+new Date(i.created_at+"Z").toLocaleString("fr-FR")+'</p><div class="detail-content">'+esc(i.content).replace(/\n/g,"<br>")+'</div>'+photoGallery(i.photos)+'</div>');$("backToItems").onclick=back}catch(err){alert("Impossible d’ouvrir : "+err.message)}return}
 const note=e.target.closest("[data-private-note]");if(note){const id=note.dataset.privateNote;const d=await api("/private-notes"),n=d.notes.find(x=>String(x.id)===id);if(!n)return;shell("chef","🔒 "+esc(n.title),'<div class="panel detail-panel"><button class="button secondary" id="backPrivate">← Retour à mes notes</button><div class="detail-content">'+esc(n.content).replace(/\n/g,"<br>")+'</div>'+photoGallery(n.photos)+'</div>');$("backPrivate").onclick=()=>render("chef")}
 const userAct=e.target.closest("[data-user-save]");if(userAct){const id=userAct.dataset.userSave,card=userAct.closest(".user-admin-card"),team=card.querySelector("[name=team]").value,role=card.querySelector("[name=role]").value,active=card.querySelector("[name=active]").checked,is_leader=active&&role==="eleve"&&!!team&&card.querySelector("[name=is_leader]").checked,password=card.querySelector("[name=password]").value;const payload={team,role,is_leader,active};if(password)payload.password=password;if(!active&&!confirm("Désactiver ce compte ? Ses sessions seront immédiatement révoquées."))return;try{await api("/users/"+id,{method:"PATCH",body:JSON.stringify(payload)});card.querySelector("[name=password]").value="";flash(card.querySelector(".user-msg"),"Compte mis à jour. Les sessions ont été révoquées si le mot de passe a changé ou si le compte a été désactivé.",true);loadUsers()}catch(err){flash(card.querySelector(".user-msg"),friendlyAccountError(err.message))}}
});
function friendlyAccountError(message){const map={forbidden:"Action réservée aux administrateurs.",last_active_admin:"Impossible : il doit rester au moins un administrateur actif.",cannot_deactivate_self:"Tu ne peux pas désactiver ton propre compte.",cannot_change_own_role:"Tu ne peux pas modifier ton propre rôle.",invalid_role:"Rôle invalide.",invalid_team:"Équipe invalide.",prof_cannot_be_assigned_team:"Un compte professeur ne peut pas être affecté à une équipe.",leader_needs_active_student_team:"Seul un élève actif affecté à une équipe peut être chef d’équipe.",password_too_short:"Le mot de passe doit contenir au moins 8 caractères.",username_exists:"Cet identifiant existe déjà.",invalid_username:"Identifiant invalide : 3 à 40 caractères (lettres, chiffres, point, tiret ou souligné)."};return map[message]||message}
async function loadUsers(){try{const d=await api("/users");$("users").innerHTML=d.users.map(u=>'<div class="user-admin-card '+(u.active?"":"user-inactive")+'" data-user-id="'+u.id+'"><div class="user-admin-head"><b>'+esc(u.username)+'</b><span class="account-status '+(u.active?"account-active":"account-disabled")+'">'+(u.active?"Actif":"Désactivé")+(Number(u.id)===Number(me.id)?" · Ton compte":"")+'</span></div><div class="admin-controls"><label>Rôle<select name="role" '+(Number(u.id)===Number(me.id)?"disabled":"")+'>'+["eleve","prof","admin"].map(r=>'<option value="'+r+'" '+(u.role===r?"selected":"")+'>'+({eleve:"Élève",prof:"Professeur",admin:"Administrateur"}[r])+'</option>').join("")+'</select></label><label>Équipe<select name="team"><option value="">Aucune / à choisir</option>'+teams.map(t=>'<option value="'+t[0]+'" '+(u.team===t[0]?"selected":"")+'>'+t[1]+'</option>').join("")+'</select></label><label class="leader-check"><input type="checkbox" name="is_leader" '+(u.is_leader?"checked":"")+' '+(u.role!=="eleve"||!u.team||!u.active?"disabled":"")+'> Chef d’équipe</label><label class="leader-check"><input type="checkbox" name="active" '+(u.active?"checked":"")+(Number(u.id)===Number(me.id)?" disabled":"")+'> Compte actif</label><label class="password-reset">Nouveau mot de passe (facultatif)<input name="password" type="password" minlength="8" maxlength="256" autocomplete="new-password" placeholder="Laisser vide pour ne pas changer" '+(Number(u.id)===Number(me.id)?"disabled":"")+'></label></div><button class="button" data-user-save="'+u.id+'">Enregistrer</button><p class="user-msg" hidden></p></div>').join("")}catch(e){$("users").textContent=e.message}}
async function loadPrivateNotes(){try{const d=await api("/private-notes");$("privateNotes").innerHTML=d.notes.length?d.notes.map(n=>'<button class="item-card" data-private-note="'+n.id+'"><span class="item-title">'+esc(n.title)+'</span><span class="item-meta">'+new Date(n.updated_at+"Z").toLocaleString("fr-FR")+'</span><span class="item-preview">'+esc(n.content.slice(0,130))+'</span>'+(n.photos?.length?'<span class="photo-count">📷 / schémas : '+n.photos.length+'</span>':'')+'<span class="item-open">Ouvrir la note privée →</span></button>').join(""):'<p class="notice">Aucune note privée enregistrée.</p>'}catch(e){$("privateNotes").textContent=e.message}}
function initSketch(){const canvas=$("sketchCanvas");if(!canvas)return;const ctx=canvas.getContext("2d");ctx.lineWidth=3;ctx.lineCap="round";ctx.strokeStyle="#17202a";let drawing=false;const pos=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y)};canvas.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();sketchDirty=true};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);$("clearSketch").onclick=clearSketch}
function clearSketch(){const c=$("sketchCanvas");if(!c)return;const ctx=c.getContext("2d");ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle="#fff";ctx.fillRect(0,0,c.width,c.height);sketchDirty=false}

async function loadAiJournal(){try{const d=await api("/ai/journal"),el=$("aiJournalEntries");if(!el)return;el.innerHTML=d.entries.length?d.entries.map(n=>'<article class="ai-entry"><div class="item-meta">'+esc(n.entry_date)+' · Généré le '+new Date(n.generated_at+"Z").toLocaleString("fr-FR")+'</div><h3>'+esc(n.title)+'</h3><div class="detail-content">'+esc(n.content).replace(/\n/g,"<br>")+'</div></article>').join(""):'<p class="notice">Aucun journal de bord IA pour le moment. L’administrateur pourra en générer un pour une journée.</p>'}catch(e){const el=$("aiJournalEntries");if(el)el.textContent="Impossible de charger : "+e.message}}
async function loadAiSuggestions(){try{const d=await api("/ai/suggestions"),el=$("aiSuggestions");if(!el)return;el.innerHTML=d.suggestions.length?d.suggestions.map(s=>'<article class="ai-entry"><div class="item-meta">Idée proposée le '+esc(s.entry_date)+' · '+new Date(s.created_at+"Z").toLocaleString("fr-FR")+'</div><h3>'+esc(s.title)+'</h3><div class="detail-content">'+esc(s.content).replace(/\n/g,"<br>")+'</div></article>').join(""):'<p class="notice">Les idées apparaîtront ici après la génération d’un journal par l’administrateur.</p>'}catch(e){const el=$("aiSuggestions");if(el)el.textContent="Impossible de charger : "+e.message}}
boot();
